uv4 = uv2*.1 +tstars*vec2( 1.0 ,0.02)+ gnd*0.002*gmask;
smask = texture(sampler_pw_noise_lq,uv4)>.8;
stars = 1.0 / length(abs(fract(uv4 * 256.0)-.5))*smask;
uv4 = uv2*.1 +tstars*vec2(0.02, 1.0 ) + gnd*0.002*gmask;
smask = texture(sampler_pw_noise_lq,uv4)>.8;
stars += 1.0 / length(abs(fract(uv4 * 256.0)-.5))*smask;
stars *= stars*0.0003;
ret.b += (1.0 - uv.y)*0.25;
ret += gnd*gmask*(.15+stars * 8.0)*abo;
ret += stars* zblend;
ret = sat(ret);
