ret += 0.0001/pow(length(uv1+(gnd1-gnd2) * 0.0), 2.0 )*gcol;
uv1 = ((uv0-0.5)-vec2(q5,-q6))*uAspect.xy;
ret += 0.00005/pow(length(uv1+dref), 2.0 )*abo*gcol*gnd;
//Glas
float refl = GetBlur1(uv0+dz*0.25).g / 2.0;
ret += refl*(1.0 + roam_cos);
ret = vec3( 1.0 ) - exp(-ret * 2.0);
  fragColor = vec4(ret, 1.0);
}

