// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_pw_noise_lq;
float stars, smask, gmask,smoke;
vec2 dz, uv0, uv1,uv2, uv3, uv4;
vec3 rs, rs2, rs0, gnd, gnd1, gnd2,screen;
const vec3 t = vec3(q20,q23,q26), s = vec3(q22,q25,q28);
const vec3 ts = cross(t,s);
const vec2 hor = (vec2(1.0)/uTexSize)*vec2( 2.0 , 0.0 ), ver = (vec2(1.0)/uTexSize)*vec2( 0.0 , 2.0 );
const vec3 centre = vec3(q7,q8,q9);
const float abo=sat(40.0 * q27), gk = max( 1.0 ,10.0 / q9), tstars = uTime*0.01;
vec3 col (float c) {return pow (c,1+1.5*roam_sin);}
vec2 noise3 (vec2 uvi) {uvi*=0.75;
return sat(texture(sampler_noise_hq,uvi)
+texture(sampler_noise_hq,uvi * 4.0) / 3.0-0.4); }
vec3 tile (vec2 uvi)
{vec3 tmp = texture(sampler_noise_lq,uvi * 40.0*texture(sampler_pw_noise_lq,uvi));
return texture(sampler_pw_noise_lq,uvi) - 0.15*tmp.xyz;}
vec3 project () {float z;
z = .08/multiply(ts,screen) ;
return vec3((multiply(float2x3(t,s),cross(ts,cross(centre,screen)))*z),-z);}
//-------------------------------------------
//Written by martin

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv += 0.0 * (vec2(1.0)/uTexSize) / 2.0; uv0 = uv;
dz.x = 2.0*GetBlur1(uv+hor*gk).g-2.0*GetBlur1(uv-hor*gk).g;
dz.y = 2.0*GetBlur1(uv+ver*gk).g-2.0*GetBlur1(uv-ver*gk).g;
dz *= GetBlur1(uv).g > 0.06;
dz *= max( 1.0 ,GetBlur2(uv).g * 7.0);
screen = vec3 ((uv-0.5)*uAspect.xy+dz*0.25, 1.0 );
rs = project(); float lrs = length(rs.xy);
gmask = sat (2-3.5*lrs);
uv2 = rs / 8.0;
uv2 *= 1.0 / (1.0 + lrs*0.3);
//uv2 += (texture(sampler_noise_lq,uv2))*0.01;
gnd1 = tile(uv2);
gnd2 = tile(uv2+0.00022*vec2(q17,q18));
gmask = sat (gmask * 3.0-2*dot(gnd1,gnd1));
gnd  = gnd1 + lum(gnd1-gnd2) * 3.0;
float zblend = sat(4.0 * abs(q27)-lrs / 8.0);
smoke = 0.04*noise3(uv2-uTime*0.04).x* zblend;
stars = 0; smask = 0;
uv4 = uv2*.1 +tstars*vec2( 1.0 ,0.02)+ gnd*0.002*gmask;
smask = texture(sampler_pw_noise_lq,uv4)>.8;
stars = 1.0 / length(abs(fract(uv4 * 256.0)-.5))*smask;
uv4 = uv2*.1 +tstars*vec2(0.02, 1.0 ) + gnd*0.002*gmask;
smask = texture(sampler_pw_noise_lq,uv4)>.8;
stars += 1.0 / length(abs(fract(uv4 * 256.0)-.5))*smask;
stars *= stars*0.0003;
ret.b += (1.0 - uv.y)*0.25;
ret += gnd*gmask*(.15+stars * 8.0)*abo;
ret += stars* zblend;
ret = sat(ret);
// Dioden
uv4 = uv0+dz*0.05;
vec3 dio = max(1.5*max(GetPixel(uv4).r,GetBlur1(uv4).r),GetBlur3(uv4).r);
ret += col(dio)*q3;
// Spiegelung
vec2 dref = (gnd1-gnd2).xy*0.1;
vec2 uvm = uv4-dref;
vec3 mirr = GetBlur1(uvm).b;
ret += gmask*abo * (uv0.y < 0.99)* (uv0.y > 0.01)* col(mirr)*(1.0 + gnd) ;
//smoke
ret += smoke*q19;
vec3 gcol = audioHigh * 2.0;
uv1 = ((uv0-0.5)-vec2(q15,-q16))*uAspect.xy+dz*0.2;
ret += 0.0001/pow(length(uv1+(gnd1-gnd2) * 0.0), 2.0 )*gcol;
uv1 = ((uv0-0.5)-vec2(q5,-q6))*uAspect.xy;
ret += 0.00005/pow(length(uv1+dref), 2.0 )*abo*gcol*gnd;
//Glas
float refl = GetBlur1(uv0+dz*0.25).g / 2.0;
ret += refl*(1.0 + roam_cos);
ret = vec3( 1.0 ) - exp(-ret * 2.0);
  fragColor = vec4(ret, 1.0);
}

