float2 noise3 (float2 uvi) {uvi*=0.75;
return sat(tex2D(sampler_noise_hq,uvi)
+tex2D(sampler_noise_hq,uvi*4)/3-0.4); }
float3 tile (float2 uvi)
{float3 tmp = tex2D(sampler_noise_lq,uvi*40*tex2D(sampler_pw_noise_lq,uvi));
return tex2D(sampler_pw_noise_lq,uvi) - 0.15*tmp.xyz;}
float3 project () {float z;
z = .08/mul(ts,screen) ;
return float3((mul(float2x3(t,s),cross(ts,cross(centre,screen)))*z),-z);}
//-------------------------------------------
//Written by martin
shader_body {
uv += 0*texsize.zw/2; uv0 = uv;
dz.x = 2.0*GetBlur1(uv+hor*gk).g-2.0*GetBlur1(uv-hor*gk).g;
dz.y = 2.0*GetBlur1(uv+ver*gk).g-2.0*GetBlur1(uv-ver*gk).g;
dz *= GetBlur1(uv).g > 0.06;
dz *= max(1,GetBlur2(uv).g*7);
screen = float3 ((uv-0.5)*aspect.xy+dz*0.25,1);
rs = project(); float lrs = length(rs.xy);
gmask = sat (2-3.5*lrs);
uv2 = rs/8;
uv2 *= 1/(1+lrs*0.3);
//uv2 += (tex2D(sampler_noise_lq,uv2))*0.01;
gnd1 = tile(uv2);
gnd2 = tile(uv2+0.00022*float2(q17,q18));
gmask = sat (gmask*3-2*dot(gnd1,gnd1));
gnd  = gnd1 + lum(gnd1-gnd2)*3;
float zblend = sat(4*abs(q27)-lrs/8);
smoke = 0.04*noise3(uv2-time*0.04).x* zblend;
stars = 0; smask = 0;
uv4 = uv2*.1 +tstars*float2(1,0.02)+ gnd*0.002*gmask;
smask = tex2D (sampler_pw_noise_lq,uv4)>.8;
stars = 1/length(abs(frac(uv4*256)-.5))*smask;
uv4 = uv2*.1 +tstars*float2(0.02,1) + gnd*0.002*gmask;
smask = tex2D (sampler_pw_noise_lq,uv4)>.8;
stars += 1/length(abs(frac(uv4*256)-.5))*smask;
stars *= stars*0.0003;
ret.b += (1-uv.y)*0.25;
ret += gnd*gmask*(.15+stars*8)*abo;
ret += stars* zblend;
ret = sat(ret);
// Dioden
uv4 = uv0+dz*0.05;
float3 dio = max(1.5*max(GetPixel(uv4).r,GetBlur1(uv4).r),GetBlur3(uv4).r);
ret += col(dio)*q3;
// Spiegelung
float2 dref = (gnd1-gnd2).xy*0.1;
float2 uvm = uv4-dref;
float3 mirr = GetBlur1(uvm).b;
ret += gmask*abo * (uv0.y < 0.99)* (uv0.y > 0.01)* col(mirr)*(1+gnd) ;
//smoke
ret += smoke*q19;
float3 gcol = treb*2;
uv1 = ((uv0-0.5)-float2(q15,-q16))*aspect.xy+dz*0.2;
ret += 0.0001/pow(length(uv1+(gnd1-gnd2)*0),2)*gcol;
uv1 = ((uv0-0.5)-float2(q5,-q6))*aspect.xy;
ret += 0.00005/pow(length(uv1+dref),2)*abo*gcol*gnd;
//Glas
float refl = GetBlur1(uv0+dz*0.25).g/2;
ret += refl*(1+roam_cos);
ret = 1-exp(-ret*2);
}

